import{_ as a,o as e,c as o,a2 as l}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 11 章 文件与目录：整理、搜索、批量处理","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 文件与目录：整理、搜索、批量处理.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 文件与目录：整理、搜索、批量处理.md"}'),s={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 文件与目录：整理、搜索、批量处理.md"};function n(i,t,d,r,p,c){return e(),o("div",null,[...t[0]||(t[0]=[l(`<h1 id="第-11-章-文件与目录-整理、搜索、批量处理" tabindex="-1">第 11 章 文件与目录：整理、搜索、批量处理 <a class="header-anchor" href="#第-11-章-文件与目录-整理、搜索、批量处理" aria-label="Permalink to &quot;第 11 章 文件与目录：整理、搜索、批量处理&quot;">​</a></h1><h2 id="_11-1-场景" tabindex="-1">11.1 场景 <a class="header-anchor" href="#_11-1-场景" aria-label="Permalink to &quot;11.1 场景&quot;">​</a></h2><p>电脑里的文件越堆越多，找东西越来越难。文件类任务包括：</p><ul><li><strong>整理</strong>：归档、重命名、统一格式；</li><li><strong>搜索</strong>：按文件名找、按内容找；</li><li><strong>批量处理</strong>：成百上千个文件的统一操作。</li></ul><h2 id="_11-2-找文件-用对工具" tabindex="-1">11.2 找文件：用对工具 <a class="header-anchor" href="#_11-2-找文件-用对工具" aria-label="Permalink to &quot;11.2 找文件：用对工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>工具</th><th>示例</th></tr></thead><tbody><tr><td>按文件名/扩展名找</td><td>Glob</td><td><code>**/*.md</code> 找所有 Markdown</td></tr><tr><td>按内容找</td><td>Grep</td><td>搜 &quot;TODO&quot; 或函数名</td></tr><tr><td>看目录结构</td><td>目录列表</td><td>了解项目布局</td></tr><tr><td>看文件内容</td><td>Read</td><td>读具体文件</td></tr></tbody></table><p><strong>黄金法则：找文件用 Glob，搜内容用 Grep。</strong> 不要让我用命令行的 find/grep 绕路——专用工具更快、更安全、更好追踪。</p><h2 id="_11-3-案例-整理一个混乱的下载目录" tabindex="-1">11.3 案例：整理一个混乱的下载目录 <a class="header-anchor" href="#_11-3-案例-整理一个混乱的下载目录" aria-label="Permalink to &quot;11.3 案例：整理一个混乱的下载目录&quot;">​</a></h2><p><strong>指令：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>整理 downloads/ 目录：</span></span>
<span class="line"><span>- 图片 → 按年月归档到 photos/2026-08/</span></span>
<span class="line"><span>- 文档 → 按类型归档到 docs/{pdf,word,sheet}/</span></span>
<span class="line"><span>- 其他 → 移到 archive/</span></span>
<span class="line"><span>先给出整理计划（会移动哪些文件），我确认后再执行。</span></span></code></pre></div><p><strong>我的做法：</strong></p><ol><li>先列出目录全貌（文件数、类型分布）；</li><li>生成&quot;整理计划表&quot;：每个文件的去向你都能看到；</li><li>你确认后执行；</li><li>输出变更日志（哪些文件去了哪里），可回退。</li></ol><h2 id="_11-4-批量处理-安全第一" tabindex="-1">11.4 批量处理：安全第一 <a class="header-anchor" href="#_11-4-批量处理-安全第一" aria-label="Permalink to &quot;11.4 批量处理：安全第一&quot;">​</a></h2><p>批量操作最容易出事，所以规矩更多：</p><ul><li><strong>先统计后动手</strong>：&quot;共有 342 个文件要移动&quot;；</li><li><strong>先试运行</strong>：能模拟就先模拟；</li><li><strong>保留日志</strong>：每一步操作都有记录，可撤销；</li><li><strong>不可逆操作前必须确认</strong>：删除、覆盖、改名冲突。</li></ul><h2 id="_11-5-内容搜索的进阶用法" tabindex="-1">11.5 内容搜索的进阶用法 <a class="header-anchor" href="#_11-5-内容搜索的进阶用法" aria-label="Permalink to &quot;11.5 内容搜索的进阶用法&quot;">​</a></h2><ul><li>正则表达式：<code>err.*\\d{4}</code> 精确匹配；</li><li>大小写不敏感：搜 <code>readme</code> 时同时匹配 <code>README</code>；</li><li>限定文件类型：只在 <code>*.rs</code> 或 <code>*.md</code> 里搜；</li><li>多个条件组合：一次搜多个模式。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>例：在 src/ 里搜所有包含 &quot;TODO&quot; 或 &quot;FIXME&quot; 的代码行</span></span></code></pre></div><h2 id="_11-6-练习" tabindex="-1">11.6 练习 <a class="header-anchor" href="#_11-6-练习" aria-label="Permalink to &quot;11.6 练习&quot;">​</a></h2><ol><li>让我用 Glob 列出某个目录下的全部文件，按类型统计；</li><li>给我一个真实的整理需求，要求&quot;先出计划再执行&quot;；</li><li>用 Grep 搜一个你关心的关键词，看看有什么发现。</li></ol><blockquote><p>小结：文件任务的精髓是**&quot;先看清楚，再动手，动完留痕&quot;**。批量操作不怕慢，就怕不可逆。</p></blockquote>`,21)])])}const _=a(s,[["render",n]]);export{u as __pageData,_ as default};
